import {calculateTips} from './shift-tools.js?v=0.23.0';
export function tipPeriod(d){if(['lunch','dinner'].includes(d.tipPeriod))return d.tipPeriod;const at=Date.parse(d.orderPlacedAt);if(!Number.isFinite(at))return 'unknown';const hour=Number(new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',hour:'2-digit',hourCycle:'h23'}).format(new Date(at)));return hour<16?'lunch':'dinner';}
export function dinnerTips(state,shiftId){return state.deliveries.filter(d=>d.shiftId===shiftId&&!d.recoveryOf&&d.status!=='canceled'&&tipPeriod(d)==='dinner'&&Number.isSafeInteger(d.tipCents)&&d.tipCents>=0);}
export function calculateOrderTips(state,shiftId,serverCount,extras=[]){const orders=dinnerTips(state,shiftId);if(!orders.length)throw Error('No dinner tickets with a recorded tip. Review each ticket’s tip period first.');const entries=[...orders.map(d=>({ticket:'Order '+(d.ticket||d.id),amount:(d.tipCents/100).toFixed(2)})),...extras.map(e=>({ticket:e.ticket,amount:(e.cents/100).toFixed(2)}))];return {...calculateTips(entries,serverCount),basis:'orders',orderTipIds:orders.map(d=>d.id),extraTips:extras,calculation:'Dinner ticket tips + separately added late tips'};}
export function addLateTip(saved,amount){if(!saved)throw Error('Calculate the shift’s tips first.');const extra=calculateTips([{ticket:'Late tip',amount}],saved.serverCount).tickets[0],result=calculateTips([...saved.tickets.map(x=>({ticket:x.ticket,amount:(x.cents/100).toFixed(2)})),{ticket:'Late tip',amount:(extra.cents/100).toFixed(2)}],saved.serverCount);return {...saved,...result,extraTips:[...(saved.extraTips||[]),extra],calculation:(saved.calculation||'Previous total')+' + '+(extra.cents/100).toFixed(2)};}
export function editTicketTip(state,id,tipCents,period,at){const d=state.deliveries.find(x=>x.id===id);if(!d||!Number.isSafeInteger(tipCents)||tipCents<0||tipCents>100000000||!['auto','lunch','dinner'].includes(period))throw Error('Enter a valid tip and service period.');d.tipCents=tipCents;d.tipPeriod=period;d.tipEditedAt=at;const shift=state.shifts.find(s=>s.id===d.shiftId);if(shift?.tips?.basis==='orders'){const eligible=dinnerTips(state,shift.id);shift.tips=eligible.length?{...calculateOrderTips(state,shift.id,shift.tips.serverCount,shift.tips.extraTips||[]),updatedAt:at}:{...calculateTips([{ticket:'No dinner ticket tips',amount:'0'},...(shift.tips.extraTips||[]).map(e=>({ticket:e.ticket,amount:(e.cents/100).toFixed(2)}))],shift.tips.serverCount),basis:'orders',orderTipIds:[],extraTips:shift.tips.extraTips||[],updatedAt:at};}return d;}
export function mergeTicketSections(previous,next){if(!previous)return structuredClone(next);if(previous.ticket&&next.ticket&&previous.ticket!==next.ticket)throw Error('These sections show different order numbers. Scan sections from the same ticket.');const result={...previous},conflicts=new Set(previous.review_fields||[]);for(const k of ['name','phone','address','ticket','tipCents']){if(next[k]==null||next[k]==='')continue;if(result[k]==null||result[k]==='')result[k]=next[k];else if(result[k]!==next[k])conflicts.add(k);}const a=previous.items||[],b=next.items||[],same=(x,y)=>x.name.trim().toLowerCase()===y.name.trim().toLowerCase()&&x.quantity===y.quantity;let overlap=0;for(let n=1;n<=Math.min(a.length,b.length);n++)if(a.slice(-n).every((x,i)=>same(x,b[i])))overlap=n;result.items=[...a,...b.slice(overlap)].slice(0,60);result.review_fields=[...conflicts];result.uncertain_fields=[...new Set([...(previous.uncertain_fields||[]),...(next.uncertain_fields||[])])].filter(k=>!result[k]);return result;}
export function syncOrderTipTotals(state){for(const shift of state.shifts){if(shift.tips?.basis!=='orders')continue;const extras=shift.tips.extraTips||[],orders=dinnerTips(state,shift.id);shift.tips=orders.length?{...shift.tips,...calculateOrderTips(state,shift.id,shift.tips.serverCount,extras)}:{...shift.tips,...calculateTips([{ticket:'No dinner ticket tips',amount:'0'},...extras.map(e=>({ticket:e.ticket,amount:(e.cents/100).toFixed(2)}))],shift.tips.serverCount),orderTipIds:[]};}}
